import assert from "node:assert/strict";
import { describe, it } from "node:test";
// @ts-expect-error contract.mjs is dynamically generated by test script
import { MAX_PENALTY_BPS, TimeLockedVaultContract, deriveKey, getReleaseHash } from "../../.test-build/contract.mjs";

const NOW = Date.parse("2026-09-14T12:00:00.000Z");
const TOMORROW = NOW + 24 * 60 * 60 * 1000;

function contract(userSecret = "") {
  const instance = new TimeLockedVaultContract();
  instance.initialize("treasury-1", userSecret);
  return instance;
}

function createStrict(instance = contract()) {
  return instance.createVault({
    owner: "alice", asset: "tDUST", amount: 100n, unlockTime: TOMORROW,
    lockType: "STRICT", penaltyBps: 0, now: NOW
  });
}

function rejects(fn: () => void, code: string) {
  assert.throws(fn, (error: any) => error.code === code);
}

describe("time-locked vault contract", () => {
  it("initializes once and rejects re-initialization", () => {
    const instance = new TimeLockedVaultContract();
    instance.initialize("treasury-1");
    assert.equal(instance.isInitialized(), true);
    rejects(() => instance.initialize("treasury-2"), "ALREADY_INITIALIZED");
  });

  it("rejects an empty treasury and an uninitialized contract", () => {
    rejects(() => new TimeLockedVaultContract().initialize(" "), "INVALID_TREASURY");
    rejects(() => new TimeLockedVaultContract().createVault({
      owner: "alice", asset: "tDUST", amount: 1n, unlockTime: TOMORROW,
      lockType: "STRICT", penaltyBps: 0, now: NOW
    }), "NOT_INITIALIZED");
  });

  it("creates valid vaults with unique ids", () => {
    const instance = contract();
    assert.equal(createStrict(instance).id, 1);
    assert.equal(instance.createVault({
      owner: "alice", asset: "tDUST", amount: 5n, unlockTime: TOMORROW + 1,
      lockType: "STRICT", penaltyBps: 0, now: NOW
    }).id, 2);
  });

  it("rejects zero amounts, past unlocks, invalid modes, and oversized penalties", () => {
    rejects(() => contract().createVault({
      owner: "alice", asset: "tDUST", amount: 0n, unlockTime: TOMORROW,
      lockType: "STRICT", penaltyBps: 0, now: NOW
    }), "INVALID_AMOUNT");
    rejects(() => contract().createVault({
      owner: "alice", asset: "tDUST", amount: 1n, unlockTime: NOW - 1,
      lockType: "STRICT", penaltyBps: 0, now: NOW
    }), "INVALID_UNLOCK");
    rejects(() => contract().createVault({
      owner: "alice", asset: "tDUST", amount: 1n, unlockTime: TOMORROW,
      lockType: "BROKEN", penaltyBps: 0, now: NOW
    }), "INVALID_LOCK_TYPE");
    assert.equal(MAX_PENALTY_BPS, 10_000);
    rejects(() => contract().createVault({
      owner: "alice", asset: "tDUST", amount: 1n, unlockTime: TOMORROW,
      lockType: "PENALTY", penaltyBps: 10_001, now: NOW
    }), "INVALID_PENALTY");
  });

  it("keeps amount out of the public vault projection", () => {
    const instance = contract();
    createStrict(instance);
    const pub = instance.listPublicVaults("alice")[0];
    assert.equal(pub.id, 1);
    assert.equal(pub.asset, "tDUST");
    assert.equal(pub.lockType, "STRICT");
    assert.equal(pub.status, "ACTIVE");
    assert.equal(pub.vaultState, "LOCKED");
    // amount is NOT in public projection
    assert.equal((pub as any).amount, undefined);
  });

  it("rejects early strict withdrawal and unauthorized withdrawal", () => {
    const instance = contract();
    const vault = createStrict(instance);
    const callerProof = ""; // userSecret is empty string by default
    rejects(() => instance.withdraw(vault.id, "alice", callerProof, NOW + 1), "STILL_LOCKED");
    rejects(() => instance.withdraw(vault.id, "bob", "wrong-secret", TOMORROW), "UNAUTHORIZED");
    assert.equal(instance.getVault(vault.id).status, "ACTIVE");
  });

  it("allows strict withdrawal at unlock and blocks double withdrawal", () => {
    const instance = contract();
    const vault = createStrict(instance);
    const callerProof = "";
    const result = instance.withdraw(vault.id, "alice", callerProof, TOMORROW);
    assert.equal(result.penalty, 0n);
    assert.equal(result.ownerPayout, 100n);
    assert.equal(result.vault.status, "WITHDRAWN");
    // Double withdrawal fails because vault status is WITHDRAWN
    rejects(() => instance.withdraw(vault.id, "alice", callerProof, TOMORROW + 1), "ALREADY_WITHDRAWN");
  });

  it("rejects a missing vault", () => {
    rejects(() => contract().withdraw(999, "alice", "", TOMORROW), "VAULT_NOT_FOUND");
  });

  it("calculates early penalty and treasury accounting correctly", () => {
    const instance = contract();
    const vault = instance.createVault({
      owner: "alice", asset: "tDUST", amount: 10_000n, unlockTime: TOMORROW,
      lockType: "PENALTY", penaltyBps: 500, now: NOW
    });
    const callerProof = "";
    const result = instance.withdrawWithPenalty(vault.id, "alice", callerProof, NOW + 1, 500);
    assert.equal(result.penalty, 500n);
    assert.equal(result.ownerPayout, 9_500n);
    assert.equal(instance.getTreasury().balance, 500n);
  });

  it("charges no penalty after a penalty vault unlocks", () => {
    const instance = contract();
    const vault = instance.createVault({
      owner: "alice", asset: "tDUST", amount: 1_000n, unlockTime: TOMORROW,
      lockType: "PENALTY", penaltyBps: 500, now: NOW
    });
    const callerProof = "";
    const result = instance.withdrawWithPenalty(vault.id, "alice", callerProof, TOMORROW, 500);
    assert.equal(result.penalty, 0n);
    assert.equal(result.ownerPayout, 1_000n);
    assert.equal(instance.getTreasury().balance, 0n);
  });

  it("normalizes strict mode penalty to zero", () => {
    const vault = contract().createVault({
      owner: "alice", asset: "tDUST", amount: 10n, unlockTime: TOMORROW,
      lockType: "STRICT", penaltyBps: 500, now: NOW
    });
    assert.equal(vault.penaltyBps, 0);
  });

  it("records confirmed history and round-trips bigint state", () => {
    const instance = contract();
    const vault = instance.createVault({
      owner: "alice", asset: "tDUST", amount: 12345678901234567890n,
      unlockTime: TOMORROW, lockType: "PENALTY", penaltyBps: 125, now: NOW
    });
    const callerProof = "";
    instance.withdrawWithPenalty(vault.id, "alice", callerProof, NOW + 1, 125);
    const txKinds = instance.listTransactions("alice").map((t: { kind: string }) => t.kind);
      assert.deepEqual(txKinds, ["PENALTY_WITHDRAW", "CREATE"]);
    const restored = TimeLockedVaultContract.fromJSON(instance.toJSON());
    assert.equal(restored.getVault(vault.id).amount, 12345678901234567890n);
    assert.equal(restored.getTreasury().balance, 154320986265432098n);
  });

  it("rejects unauthorized withdrawal after initialization reset", () => {
    const instance = contract();
    const vault = createStrict(instance);
    rejects(() => instance.withdraw(vault.id, "eve", "wrong-secret", TOMORROW), "UNAUTHORIZED");
  });

  it("deriveKey produces deterministic keys", () => {
    assert.equal(deriveKey("secret"), deriveKey("secret"));
    assert.notEqual(deriveKey("secret1"), deriveKey("secret2"));
  });

  it("ownerPublicKey is derived from userSecret", () => {
    const instance = contract("my-secret");
    assert.equal(instance.getOwnerPublicKey(), deriveKey("my-secret"));
  });

  it("enforces multi-user vault ownership isolation", () => {
    const instance = contract("deployer-secret");
    const aliceVault = instance.createVault({
      owner: "alice", ownerSecret: "alice-secret", asset: "tDUST", amount: 100n,
      unlockTime: TOMORROW, lockType: "STRICT", penaltyBps: 0, now: NOW
    });
    const bobVault = instance.createVault({
      owner: "bob", ownerSecret: "bob-secret", asset: "tDUST", amount: 200n,
      unlockTime: TOMORROW, lockType: "STRICT", penaltyBps: 0, now: NOW
    });

    // Deployer cannot withdraw Alice's vault
    rejects(() => instance.withdraw(aliceVault.id, "deployer", "deployer-secret", TOMORROW), "UNAUTHORIZED");
    // Bob cannot withdraw Alice's vault
    rejects(() => instance.withdraw(aliceVault.id, "bob", "bob-secret", TOMORROW), "UNAUTHORIZED");
    // Alice can withdraw her own vault
    const aliceResult = instance.withdraw(aliceVault.id, "alice", "alice-secret", TOMORROW);
    assert.equal(aliceResult.ownerPayout, 100n);

    // Alice cannot withdraw Bob's vault
    rejects(() => instance.withdraw(bobVault.id, "alice", "alice-secret", TOMORROW), "UNAUTHORIZED");
    // Bob can withdraw his own vault
    const bobResult = instance.withdraw(bobVault.id, "bob", "bob-secret", TOMORROW);
    assert.equal(bobResult.ownerPayout, 200n);
  });
});

describe("Wave 2 encrypted unlock secrets", () => {
  it("creates a vault with a release secret and requires it for withdrawal", () => {
    const instance = contract();
    const vault = instance.createVault({
      owner: "alice", asset: "tDUST", amount: 500n, unlockTime: TOMORROW,
      lockType: "STRICT", penaltyBps: 0, now: NOW,
      releaseSecret: "my-secret-passphrase"
    });
    assert.ok(vault.releaseHash);
    // Cannot withdraw without secret
    rejects(() => instance.withdraw(vault.id, "alice", "", TOMORROW), "INVALID_RELEASE_SECRET");
    // Cannot withdraw with wrong secret
    rejects(() => instance.withdraw(vault.id, "alice", "", TOMORROW, "wrong-secret"), "INVALID_RELEASE_SECRET");
    // Can withdraw with correct secret
    const result = instance.withdraw(vault.id, "alice", "", TOMORROW, "my-secret-passphrase");
    assert.equal(result.ownerPayout, 500n);
  });

  it("allows withdrawal without secret when none was set", () => {
    const instance = contract();
    const vault = createStrict(instance);
    assert.equal(vault.releaseHash, undefined);
    const result = instance.withdraw(vault.id, "alice", "", TOMORROW);
    assert.equal(result.ownerPayout, 100n);
  });

  it("getReleaseHash is deterministic", () => {
    assert.equal(getReleaseHash("test"), getReleaseHash("test"));
    assert.notEqual(getReleaseHash("a"), getReleaseHash("b"));
  });

  it("requires release secret for penalty withdrawal too", () => {
    const instance = contract();
    const vault = instance.createVault({
      owner: "alice", asset: "tDUST", amount: 10000n, unlockTime: TOMORROW,
      lockType: "PENALTY", penaltyBps: 500, now: NOW,
      releaseSecret: "penalty-secret"
    });
    // Early penalty withdrawal without secret fails
    rejects(() => instance.withdrawWithPenalty(vault.id, "alice", "", NOW + 1, 500), "INVALID_RELEASE_SECRET");
    // With correct secret succeeds
    const result = instance.withdrawWithPenalty(vault.id, "alice", "", NOW + 1, 500, "penalty-secret");
    assert.equal(result.penalty, 500n);
    assert.equal(result.ownerPayout, 9500n);
  });
});

describe("Wave 2 lifecycle extension", () => {
  it("markReleasable transitions LOCKED → RELEASABLE at unlock time", () => {
    const instance = contract();
    const vault = createStrict(instance);
    assert.equal(vault.vaultState, "LOCKED");
    // Cannot mark releasable before unlock
    rejects(() => instance.markReleasable(vault.id, NOW + 1), "STILL_LOCKED");
    // Can mark releasable at unlock
    const released = instance.markReleasable(vault.id, TOMORROW);
    assert.equal(released.vaultState, "RELEASABLE");
  });

  it("rejects markReleasable on non-LOCKED vaults", () => {
    const instance = contract();
    const vault = createStrict(instance);
    instance.withdraw(vault.id, "alice", "", TOMORROW);
    rejects(() => instance.markReleasable(vault.id, TOMORROW), "INVALID_STATE");
  });

  it("records RELEASE transaction", () => {
    const instance = contract();
    createStrict(instance);
    instance.markReleasable(1, TOMORROW);
    const txKinds = instance.listTransactions("alice").map((t: { kind: string }) => t.kind);
    assert.ok(txKinds.includes("RELEASE"));
  });
});

describe("Wave 2 tDUST denomination", () => {
  it("stores dustAmount equal to amount", () => {
    const instance = contract();
    const vault = instance.createVault({
      owner: "alice", asset: "tDUST", amount: 1000n, unlockTime: TOMORROW,
      lockType: "STRICT", penaltyBps: 0, now: NOW
    });
    assert.equal(vault.dustAmount, 1000n);
    assert.equal(vault.amount, vault.dustAmount);
  });
});

describe("Wave 2 commitment hardening", () => {
  it("amount is not in public vault projection", () => {
    const instance = contract();
    createStrict(instance);
    const pub = instance.listPublicVaults("alice")[0];
    assert.equal((pub as any).amount, undefined);
    assert.equal((pub as any).dustAmount, undefined);
  });
});